const wd="C:\\Users\\User\\Documents\\ChatGPT\\Muc Legal LLT Hackathon";
const cmds=[
  "git status --short; git branch --show-current; git remote -v",
  "entire status",
  "rg -n -i \"grey|gray|grau|ki.?analyse|ai.?analysis|llm|anthropic\" reference/LOCAL_BEWEISLAB_IMPLEMENTATION_PLAN.md reference/TROUBLESHOOTING_AND_SOLUTIONS_2026-08-20.md reference/BROWSER_MODE_AUDIT.md reference/BACKEND_ALIGNMENT_2026-08-20.md",
  "rg -n -i \"grey|gray|grau|ki.?analyse|ai.?analysis|llm|anthropic\" . --glob '!reference/**' --glob '!.git/**' --glob '!.muclegal-ui/**'"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:20000})));
rs.forEach((r,i)=>{text(`---${i+1}---\n${r.output}`)});

const wd="C:\\Users\\User\\Documents\\ChatGPT\\Muc Legal LLT Hackathon";
const cmds=[
  "git log --format='%H%n%B%n---' -5 -- muclegal/live.py muclegal/llm/god_mode_summary.py muclegal/templates/evidence_lab.html tests/test_god_mode_summary.py",
  "rg -n -C 6 \"create_god_mode_editorial_analysis|grey-mode-editorial|god_mode_editorial|grey-mode-ai-usage|GOD_MODE_AI|OPENAI\" muclegal/live.py muclegal/llm/__init__.py muclegal/llm/god_mode_summary.py muclegal/templates/evidence_lab.html tests/test_live_ui.py tests/test_god_mode_summary.py .env.example README.md reference/BROWSER_MODE_AUDIT.md reference/TROUBLESHOOTING_AND_SOLUTIONS_2026-08-20.md",
  "Get-Content reference/LOCAL_BEWEISLAB_IMPLEMENTATION_PLAN.md | Select-Object -First 130",
  "Get-Content reference/BROWSER_MODE_AUDIT.md | Select-Object -Skip 70 -First 55",
  "Get-Content reference/TROUBLESHOOTING_AND_SOLUTIONS_2026-08-20.md | Select-Object -Skip 330 -First 85"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:30000})));
rs.forEach((r,i)=>text(`---${i+1}---\n${r.output}`));

const wd="C:\\Users\\User\\Documents\\ChatGPT\\Muc Legal LLT Hackathon";
const cmds=[
  "$p='muclegal/live.py'; $lines=Get-Content $p; $ranges=@(@(90,150),@(1040,1180),@(1260,1375),@(1580,1650),@(2150,2190)); foreach($r in $ranges){\"### $($r[0])-$($r[1])\"; $lines[($r[0]-1)..($r[1]-1)]}",
  "$p='muclegal/ui.py'; rg -n -C 5 \"god_mode_editorial|god_mode_ai|editorial_analysis|analysis_mode|artifact\" $p",
  "$p='tests/test_live_ui.py'; $lines=Get-Content $p; $lines[500..650]",
  "rg -n \"god_mode_editorial_builder|god_mode_editorial_summary|god_mode_ai_usage|editorial_analysis|capture_plus_non_evidentiary|optionale_openai_redaktionelle\" --glob '!muclegal/llm/god_mode_summary.py' --glob '!tests/test_god_mode_summary.py' ."
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:30000})));
rs.forEach((r,i)=>text(`---${i+1}---\n${r.output}`));

const wd="C:\\Users\\User\\Documents\\ChatGPT\\Muc Legal LLT Hackathon";
const cmds=[
  "$p='muclegal/live.py'; $l=Get-Content $p; $l[985..1030]",
  "$p='tests/test_live_ui.py'; $l=Get-Content $p; $l[650..715]",
  "Get-Content muclegal/ui.py | Select-Object -First 115",
  "Get-Content muclegal/llm/__init__.py",
  "rg -n -i \"openai|ki|analyse|editorial\" README.md reference/BROWSER_MODE_AUDIT.md reference/TROUBLESHOOTING_AND_SOLUTIONS_2026-08-20.md reference/FRONTEND_BACKEND_UEBERGABE_2026-08-21.md .env.example | rg -n -i \"grey|gray|god.mode|editorial|MUCLEGAL_OPENAI_MODEL|MUCLEGAL_OPENAI_MAX|MUCLEGAL_OPENAI_SAMPLE\""
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:20000})));
rs.forEach((r,i)=>text(`---${i+1}---\n${r.output}`));

